const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");
const fs = require("fs");

async function main() {
    try {
        const crossmint = createCrossmint({ apiKey: process.env.CROSSMINT_API_KEY });
        const wallets = CrossmintWallets.from(crossmint);

        const wallet = await wallets.createWallet({
            chain: "base-sepolia",
            recovery: { type: "server", secret: process.env.SIGNER_SECRET }
        });

        fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify({
            chain: wallet.chain,
            type: wallet.type,
            address: wallet.address
        }, null, 2));

    } catch (error) {
        fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify({
            chain: "base-sepolia",
            type: "evm",
            error: error.message
        }, null, 2));
    }
}

main();

